55	/// When a routine should fire.
56	#[derive(Debug, Clone, Serialize, Deserialize)]
57	#[serde(tag = "type", rename_all = "snake_case")]
58	pub enum Trigger {
59	    /// Fire on a cron schedule (e.g. "0 9 * * MON-FRI" or "every 2h").
60	    Cron {
61	        schedule: String,
62	        #[serde(default)]
63	        timezone: Option<String>,
64	    },
65	    /// Fire when a channel message matches a pattern.
66	    Event {
67	        /// Optional channel filter (e.g. "telegram", "slack").
68	        channel: Option<String>,
69	        /// Regex pattern to match against message content.
70	        pattern: String,
71	    },
72	    /// Fire when a structured system event is emitted.
73	    SystemEvent {
74	        /// Event source namespace (e.g. "github", "workflow", "tool").
75	        source: String,
76	        /// Event type within the source (e.g. "issue.opened").
77	        event_type: String,
78	        /// Optional exact-match filters against payload top-level fields.
79	        #[serde(default)]
80	        filters: std::collections::HashMap<String, String>,
81	    },
82	    /// Fire on incoming webhook POST to /api/webhooks/{path}.
83	    Webhook {
84	        /// Optional webhook path suffix (defaults to routine id).
85	        path: Option<String>,
86	        /// Optional shared secret for HMAC validation.
87	        secret: Option<String>,
88	    },
89	    /// Only fires via tool call or CLI.
90	    Manual,
91	}
92	
93	impl Trigger {
94	    /// The string tag stored in the DB trigger_type column.
95	    pub fn type_tag(&self) -> &'static str {
96	        match self {
97	            Trigger::Cron { .. } => "cron",
98	            Trigger::Event { .. } => "event",
99	            Trigger::SystemEvent { .. } => "system_event",
100	            Trigger::Webhook { .. } => "webhook",
101	            Trigger::Manual => "manual",
102	        }
103	    }
104	
105	    /// Parse a trigger from its DB representation.
106	    pub fn from_db(trigger_type: &str, config: serde_json::Value) -> Result<Self, RoutineError> {
107	        match trigger_type {
108	            "cron" => {
109	                let schedule = config
110	                    .get("schedule")
111	                    .and_then(|v| v.as_str())
112	                    .ok_or_else(|| RoutineError::MissingField {
113	                        context: "cron trigger".into(),
114	                        field: "schedule".into(),
115	                    })?
116	                    .to_string();
117	                let timezone = config
118	                    .get("timezone")
119	                    .and_then(|v| v.as_str())
120	                    .and_then(|tz| {
121	                        if crate::timezone::parse_timezone(tz).is_some() {
122	                            Some(tz.to_string())
123	                        } else {
124	                            tracing::warn!(
125	                                "Ignoring invalid timezone '{}' from DB for cron trigger",
126	                                tz
127	                            );
128	                            None
129	                        }
130	                    });
131	                Ok(Trigger::Cron { schedule, timezone })
132	            }
133	            "event" => {
134	                let pattern = config
135	                    .get("pattern")
136	                    .and_then(|v| v.as_str())
137	                    .ok_or_else(|| RoutineError::MissingField {
138	                        context: "event trigger".into(),
139	                        field: "pattern".into(),
140	                    })?
141	                    .to_string();
142	                let channel = config
143	                    .get("channel")
144	                    .and_then(|v| v.as_str())
145	                    .map(String::from);
146	                Ok(Trigger::Event { channel, pattern })
147	            }
148	            "system_event" => {
149	                let source = config
150	                    .get("source")
151	                    .and_then(|v| v.as_str())
152	                    .ok_or_else(|| RoutineError::MissingField {
153	                        context: "system_event trigger".into(),
154	                        field: "source".into(),
155	                    })?
156	                    .to_string();
157	                let event_type = config
158	                    .get("event_type")
159	                    .and_then(|v| v.as_str())
160	                    .ok_or_else(|| RoutineError::MissingField {
161	                        context: "system_event trigger".into(),
162	                        field: "event_type".into(),
163	                    })?
164	                    .to_string();
165	                let filters = config
166	                    .get("filters")
167	                    .and_then(|v| v.as_object())
168	                    .map(|m| {
169	                        m.iter()
170	                            .filter_map(|(k, v)| {
171	                                json_value_as_filter_string(v).map(|s| (k.clone(), s))
172	                            })
173	                            .collect()
174	                    })
175	                    .unwrap_or_default();
176	                Ok(Trigger::SystemEvent {
177	                    source,
178	                    event_type,
179	                    filters,
180	                })
181	            }
182	            "webhook" => {
183	                let path = config
184	                    .get("path")
185	                    .and_then(|v| v.as_str())
186	                    .map(String::from);
187	                let secret = config
188	                    .get("secret")
189	                    .and_then(|v| v.as_str())
190	                    .map(String::from);
191	                Ok(Trigger::Webhook { path, secret })
192	            }
193	            "manual" => Ok(Trigger::Manual),
194	            other => Err(RoutineError::UnknownTriggerType {
195	                trigger_type: other.to_string(),
196	            }),
197	        }
198	    }
