279	/// Clamp max_tool_rounds to [1, MAX_TOOL_ROUNDS_LIMIT].
280	/// Accepts u64 to avoid truncation before clamping.
281	fn clamp_max_tool_rounds(value: u64) -> u32 {
282	    value.clamp(1, MAX_TOOL_ROUNDS_LIMIT as u64) as u32
