198	
199	async fn list(
200	    db: &Arc<dyn Database>,
201	    user_id: &str,
202	    trigger_filter: Option<&str>,
203	    show_disabled: bool,
204	    json: bool,
205	) -> anyhow::Result<()> {
206	    let routines = db.list_routines(user_id).await?;
207	
208	    let filtered: Vec<&Routine> = routines
209	        .iter()
210	        .filter(|r| {
211	            trigger_filter
212	                .map(|t| r.trigger.type_tag() == t)
213	                .unwrap_or(true)
214	        })
215	        .filter(|r| show_disabled || r.enabled)
216	        .collect();
217	
218	    if json {
219	        let items: Vec<serde_json::Value> = filtered
220	            .iter()
221	            .map(|r| {
222	                serde_json::json!({
223	                    "id": r.id.to_string(),
224	                    "name": r.name,
225	                    "trigger": r.trigger.type_tag(),
226	                    "enabled": r.enabled,
227	                    "next_fire_at": r.next_fire_at,
228	                    "last_run_at": r.last_run_at,
229	                    "run_count": r.run_count,
230	                    "consecutive_failures": r.consecutive_failures,
231	                })
232	            })
233	            .collect();
234	        println!("{}", serde_json::to_string_pretty(&items)?);
235	        return Ok(());
236	    }
237	
238	    if filtered.is_empty() {
239	        if let Some(t) = trigger_filter {
240	            println!("No {t} routines found.");
241	        } else {
242	            println!("No routines found.");
243	        }
244	        return Ok(());
245	    }
246	
247	    // Header
248	    println!(
249	        "{:<36}  {:<20}  {:<8}  {:<8}  {:<22}  {:<22}  {:>5}",
250	        "ID", "NAME", "TRIGGER", "STATUS", "NEXT FIRE", "LAST RUN", "RUNS"
251	    );
252	    println!("{}", "-".repeat(130));
253	
254	    // Fetch last-run status for all routines in a single batch query
255	    let routine_ids: Vec<Uuid> = filtered.iter().map(|r| r.id).collect();
256	    let last_run_results = db
257	        .batch_get_last_run_status(&routine_ids)
258	        .await
259	        .unwrap_or_default();
260	
261	    for r in &filtered {
262	        let last_run_status = last_run_results.get(&r.id).copied();
263	
264	        let status = if !r.enabled {
265	            "disabled".to_string()
266	        } else if last_run_status == Some(RunStatus::Running) {
267	            "running".to_string()
268	        } else if r.consecutive_failures > 0 {
269	            format!("err({})", r.consecutive_failures)
270	        } else if last_run_status == Some(RunStatus::Attention) {
271	            "attention".to_string()
272	        } else {
273	            "active".to_string()
274	        };
275	
276	        let next_fire = r
277	            .next_fire_at
278	            .map(format_relative)
279	            .unwrap_or_else(|| "-".to_string());
280	
281	        let last_run = r
282	            .last_run_at
283	            .map(format_relative)
284	            .unwrap_or_else(|| "-".to_string());
285	
286	        let name = truncate(&r.name, 20);
287	
288	        println!(
289	            "{:<36}  {:<20}  {:<8}  {:<8}  {:<22}  {:<22}  {:>5}",
290	            r.id,
291	            name,
292	            r.trigger.type_tag(),
293	            status,
294	            next_fire,
295	            last_run,
296	            r.run_count,
297	        );
298	    }
299	
300	    println!("\n{} routine(s)", filtered.len());
301	    Ok(())
302	}
