316	#[allow(clippy::too_many_arguments)]
317	async fn create(
318	    db: &Arc<dyn Database>,
319	    user_id: &str,
320	    name: &str,
321	    schedule: &str,
322	    prompt: &str,
323	    description: &str,
324	    timezone: Option<&str>,
325	    cooldown_secs: u64,
326	    notify_channel: Option<String>,
327	) -> anyhow::Result<()> {
328	    validate_timezone_arg(timezone)?;
329	
330	    // Validate the cron expression by computing next fire.
331	    let next_fire = next_cron_fire(schedule, timezone)
332	        .map_err(|e| anyhow::anyhow!("Invalid cron schedule: {e}"))?;
333	
334	    // Check for name conflict.
335	    if db.get_routine_by_name(user_id, name).await?.is_some() {
336	        anyhow::bail!("Routine '{}' already exists", name);
337	    }
338	
339	    let now = Utc::now();
340	    let routine = Routine {
341	        id: Uuid::new_v4(),
342	        name: name.to_string(),
343	        description: description.to_string(),
344	        user_id: user_id.to_string(),
345	        enabled: true,
346	        trigger: Trigger::Cron {
347	            schedule: schedule.to_string(),
348	            timezone: timezone.map(String::from),
349	        },
350	        action: RoutineAction::Lightweight {
351	            prompt: prompt.to_string(),
352	            context_paths: Vec::new(),
353	            max_tokens: 4096,
354	            use_tools: true,
355	            max_tool_rounds: 3,
356	        },
357	        guardrails: RoutineGuardrails {
358	            cooldown: std::time::Duration::from_secs(cooldown_secs),
359	            max_concurrent: 1,
360	            dedup_window: None,
361	        },
362	        notify: cli_notify_config(notify_channel),
363	        last_run_at: None,
364	        next_fire_at: next_fire,
365	        run_count: 0,
366	        consecutive_failures: 0,
367	        state: serde_json::json!({}),
368	        created_at: now,
369	        updated_at: now,
370	    };
371	
372	    db.create_routine(&routine).await?;
373	
374	    println!("Created routine '{}'", name);
375	    println!("  ID:        {}", routine.id);
376	    println!("  Schedule:  {}", schedule);
377	    if let Some(tz) = timezone {
378	        println!("  Timezone:  {}", tz);
379	    }
380	    if let Some(nf) = next_fire {
381	        println!("  Next fire: {}", format_relative(nf));
382	    }
383	    Ok(())
384	}
