387	
388	#[allow(clippy::too_many_arguments)]
389	async fn edit(
390	    db: &Arc<dyn Database>,
391	    user_id: &str,
392	    name: &str,
393	    schedule: Option<&str>,
394	    prompt: Option<&str>,
395	    description: Option<&str>,
396	    timezone: Option<&str>,
397	    cooldown: Option<u64>,
398	) -> anyhow::Result<()> {
399	    let mut routine = require_routine(db, user_id, name).await?;
400	    validate_timezone_arg(timezone)?;
401	
402	    let mut changed = false;
403	
404	    // Update schedule if provided (only valid for cron routines).
405	    if let Some(new_schedule) = schedule {
406	        let tz = timezone.or(match &routine.trigger {
407	            Trigger::Cron { timezone, .. } => timezone.as_deref(),
408	            _ => None,
409	        });
410	        let next_fire = next_cron_fire(new_schedule, tz)
411	            .map_err(|e| anyhow::anyhow!("Invalid cron schedule: {e}"))?;
412	        routine.trigger = Trigger::Cron {
413	            schedule: new_schedule.to_string(),
414	            timezone: tz.map(String::from),
415	        };
416	        routine.next_fire_at = next_fire;
417	        changed = true;
418	    } else if let Some(tz) = timezone {
419	        // Update only timezone, recompute next fire with existing schedule.
420	        if let Trigger::Cron { ref schedule, .. } = routine.trigger {
421	            let next_fire = next_cron_fire(schedule, Some(tz))
422	                .map_err(|e| anyhow::anyhow!("Invalid cron schedule: {e}"))?;
423	            routine.trigger = Trigger::Cron {
424	                schedule: schedule.clone(),
425	                timezone: Some(tz.to_string()),
426	            };
427	            routine.next_fire_at = next_fire;
428	            changed = true;
429	        } else {
430	            anyhow::bail!("Cannot set timezone on non-cron trigger");
431	        }
432	    }
433	
434	    if let Some(new_prompt) = prompt {
435	        match &mut routine.action {
436	            RoutineAction::Lightweight { prompt: p, .. } => {
437	                *p = new_prompt.to_string();
438	                changed = true;
439	            }
440	            RoutineAction::FullJob { description: d, .. } => {
441	                *d = new_prompt.to_string();
442	                changed = true;
443	            }
444	        }
445	    }
446	
447	    if let Some(new_desc) = description {
448	        routine.description = new_desc.to_string();
449	        changed = true;
450	    }
451	
452	    if let Some(cd) = cooldown {
453	        routine.guardrails.cooldown = std::time::Duration::from_secs(cd);
454	        changed = true;
455	    }
456	
457	    if !changed {
458	        println!("No changes specified.");
459	        return Ok(());
460	    }
461	
462	    routine.updated_at = Utc::now();
463	    db.update_routine(&routine).await?;
464	    println!("Updated routine '{}'", name);
465	    Ok(())
466	}
