470	async fn set_enabled(
471	    db: &Arc<dyn Database>,
472	    user_id: &str,
473	    name: &str,
474	    enabled: bool,
475	) -> anyhow::Result<()> {
476	    let mut routine = require_routine(db, user_id, name).await?;
477	
478	    if routine.enabled == enabled {
479	        println!(
480	            "Routine '{}' is already {}",
481	            name,
482	            if enabled { "enabled" } else { "disabled" }
483	        );
484	        return Ok(());
485	    }
486	
487	    routine.enabled = enabled;
488	
489	    // Recompute next fire when enabling a cron routine.
490	    if enabled
491	        && let Trigger::Cron {
492	            ref schedule,
493	            ref timezone,
494	        } = routine.trigger
495	    {
496	        routine.next_fire_at = next_cron_fire(schedule, timezone.as_deref())
497	            .map_err(|e| anyhow::anyhow!("Failed to compute next fire for stored schedule: {e}"))?;
498	    }
499	
500	    routine.updated_at = Utc::now();
501	    db.update_routine(&routine).await?;
502	    println!(
503	        "{} routine '{}'",
504	        if enabled { "Enabled" } else { "Disabled" },
505	        name
506	    );
507	    Ok(())
508	}
