649	
650	/// Format a datetime relative to now (e.g. "in 2h", "3m ago").
651	fn format_relative(dt: DateTime<Utc>) -> String {
652	    let now = Utc::now();
653	    let diff = dt.signed_duration_since(now);
654	    let secs = diff.num_seconds();
655	
656	    if secs.abs() < 60 {
657	        if secs >= 0 {
658	            "in <1m".to_string()
659	        } else {
660	            "<1m ago".to_string()
661	        }
662	    } else if secs.abs() < 3600 {
663	        let mins = secs.abs() / 60;
664	        if secs >= 0 {
665	            format!("in {}m", mins)
666	        } else {
667	            format!("{}m ago", mins)
668	        }
669	    } else if secs.abs() < 86400 {
670	        let hours = secs.abs() / 3600;
671	        if secs >= 0 {
672	            format!("in {}h", hours)
673	        } else {
674	            format!("{}h ago", hours)
675	        }
676	    } else {
677	        let days = secs.abs() / 86400;
678	        if secs >= 0 {
679	            format!("in {}d", days)
680	        } else {
681	            format!("{}d ago", days)
682	        }
683	    }
684	}
685	
686	/// Truncate a string to a maximum character length.
687	fn truncate(s: &str, max_chars: usize) -> String {
688	    if s.chars().count() <= max_chars {
689	        s.to_string()
690	    } else {
691	        let truncated: String = s.chars().take(max_chars.saturating_sub(2)).collect();
692	        format!("{}..", truncated)
693	    }
694	}
