59	/// Check whether an event-triggered routine's user/channel filters match an
60	/// incoming message.
61	///
62	/// Returns `true` if:
63	/// - The routine has an `Event` trigger (non-Event routines always return `false`)
64	/// - The routine's `user_id` matches the message's user scope
65	/// - The routine's channel filter (if any) matches the message channel
66	///   case-insensitively
67	///
68	/// This is a pure function extracted from `check_event_triggers` so the
69	/// filter logic can be unit-tested without async infrastructure.
70	pub(crate) fn routine_matches_message(routine: &Routine, message: &IncomingMessage) -> bool {
71	    // Only Event-triggered routines can match incoming messages.
72	    if !matches!(routine.trigger, Trigger::Event { .. }) {
73	        return false;
74	    }
75	
76	    // User ownership filter — only fire routines scoped to this user.
77	    if routine.user_id != message.user_id {
78	        return false;
79	    }
80	
81	    // Channel filter (case-insensitive, matching emit_system_event behavior)
82	    if let Trigger::Event {
83	        channel: Some(ch), ..
84	    } = &routine.trigger
85	        && !ch.eq_ignore_ascii_case(&message.channel)
86	    {
87	        return false;
88	    }
89	
90	    true
91	}
