203	    /// Check incoming message against event triggers. Returns number of routines fired.
204	    pub async fn check_event_triggers(&self, message: &IncomingMessage, content: &str) -> usize {
205	        let cache = self.event_cache.read().await;
206	
207	        // Early return if there are no message matchers at all.
208	        if !cache
209	            .iter()
210	            .any(|m| matches!(m, EventMatcher::Message { .. }))
211	        {
212	            return 0;
213	        }
214	
215	        let mut fired = 0;
216	
217	        // Collect routine IDs for batch query
218	        let routine_ids: Vec<Uuid> = cache
219	            .iter()
220	            .filter_map(|matcher| match matcher {
221	                EventMatcher::Message { routine, .. } => Some(routine.id),
222	                EventMatcher::System { .. } => None,
223	            })
224	            .collect();
225	
226	        if routine_ids.is_empty() {
227	            return 0;
228	        }
229	
230	        // Single batch query instead of N queries
231	        let concurrent_counts = match self.batch_concurrent_counts(&routine_ids).await {
232	            Some(counts) => counts,
233	            None => return 0,
234	        };
235	
236	        for matcher in cache.iter() {
237	            let (routine, re) = match matcher {
238	                EventMatcher::Message { routine, regex } => (routine, regex),
239	                EventMatcher::System { .. } => continue,
240	            };
241	
242	            // User ownership + channel filter (extracted for testability).
243	            if !routine_matches_message(routine, message) {
244	                // User mismatch is expected for multi-user setups — keep at
245	                // trace to avoid one log per routine per inbound message.
246	                if routine.user_id != message.user_id {
247	                    tracing::trace!(
248	                        routine = %routine.name,
249	                        routine_user = %routine.user_id,
250	                        message_user = %message.user_id,
251	                        "Skipped: user scope mismatch"
252	                    );
253	                } else {
254	                    tracing::debug!(
255	                        routine = %routine.name,
256	                        channel = %message.channel,
257	                        "Skipped: channel mismatch"
258	                    );
259	                }
260	                continue;
261	            }
262	
263	            // Regex match
264	            if !re.is_match(content) {
265	                continue;
266	            }
267	
268	            // Cooldown check
269	            if !self.check_cooldown(routine) {
270	                tracing::debug!(routine = %routine.name, "Skipped: cooldown active");
271	                continue;
272	            }
273	
274	            // Concurrent run check (using batch-loaded counts)
275	            let running_count = concurrent_counts.get(&routine.id).copied().unwrap_or(0);
276	            if running_count >= routine.guardrails.max_concurrent as i64 {
277	                tracing::debug!(routine = %routine.name, "Skipped: max concurrent reached");
278	                continue;
279	            }
280	
281	            // Global capacity check
282	            if self.running_count.load(Ordering::Relaxed) >= self.config.max_concurrent_routines {
283	                tracing::warn!(routine = %routine.name, "Skipped: global max concurrent reached");
284	                continue;
285	            }
286	
287	            let detail = truncate(content, 200);
288	            self.spawn_fire(routine.clone(), "event", Some(detail));
289	            fired += 1;
290	        }
291	
292	        fired
293	    }
