295	    /// Emit a structured event to system-event routines.
296	    ///
297	    /// Returns the number of routines that were fired.
298	    pub async fn emit_system_event(
299	        &self,
300	        source: &str,

300	        source: &str,
301	        event_type: &str,
302	        payload: &serde_json::Value,
303	        user_id: Option<&str>,
304	    ) -> usize {
305	        let cache = self.event_cache.read().await;
306	
307	        // Early return if there are no system-event matchers at all.
308	        if !cache
309	            .iter()
310	            .any(|m| matches!(m, EventMatcher::System { .. }))
311	        {
312	            return 0;
313	        }
314	
315	        let mut fired = 0;
316	
317	        // Collect routine IDs for batch query
318	        let routine_ids: Vec<Uuid> = cache
319	            .iter()
320	            .filter_map(|matcher| match matcher {
321	                EventMatcher::System { routine } => Some(routine.id),
322	                EventMatcher::Message { .. } => None,
323	            })
324	            .collect();
325	
326	        if routine_ids.is_empty() {
327	            return 0;
328	        }
329	
330	        // Single batch query instead of N queries
331	        let concurrent_counts = match self.batch_concurrent_counts(&routine_ids).await {
332	            Some(counts) => counts,
333	            None => return 0,
334	        };
335	
336	        for matcher in cache.iter() {
337	            let routine = match matcher {
338	                EventMatcher::System { routine } => routine,
339	                EventMatcher::Message { .. } => continue,
340	            };
341	
342	            let Trigger::SystemEvent {
343	                source: expected_source,
344	                event_type: expected_event,
345	                filters,
346	            } = &routine.trigger
347	            else {
348	                continue;
349	            };
350	
351	            if !expected_source.eq_ignore_ascii_case(source)
352	                || !expected_event.eq_ignore_ascii_case(event_type)
353	            {
354	                continue;
355	            }
356	
357	            if let Some(uid) = user_id
358	                && routine.user_id != uid
359	            {
360	                continue;
361	            }
362	
363	            let mut matched = true;
364	            for (key, expected) in filters {
365	                let Some(actual) = payload
366	                    .get(key)
367	                    .and_then(crate::agent::routine::json_value_as_filter_string)
368	                else {
369	                    tracing::debug!(routine = %routine.name, filter_key = %key, "Filter key not found in payload");
370	                    matched = false;
371	                    break;
372	                };
373	                if !actual.eq_ignore_ascii_case(expected) {
374	                    matched = false;
375	                    break;
376	                }
377	            }
378	            if !matched {
379	                continue;
380	            }
381	
382	            if !self.check_cooldown(routine) {
383	                tracing::debug!(routine = %routine.name, "Skipped: cooldown active");
384	                continue;
385	            }
386	
387	            // Concurrent run check (using batch-loaded counts)
388	            let running_count = concurrent_counts.get(&routine.id).copied().unwrap_or(0);
389	            if running_count >= routine.guardrails.max_concurrent as i64 {
390	                tracing::debug!(routine = %routine.name, "Skipped: max concurrent reached");
391	                continue;
392	            }
393	
394	            if self.running_count.load(Ordering::Relaxed) >= self.config.max_concurrent_routines {
395	                tracing::warn!(routine = %routine.name, "Skipped: global max concurrent reached");
396	                continue;
397	            }
398	
399	            let detail = truncate(&format!("{source}:{event_type}"), 200);
400	            self.spawn_fire(routine.clone(), "system_event", Some(detail));
401	            fired += 1;
402	        }
403	
404	        fired
405	    }
