458	    /// Reconcile orphaned full_job routine runs with their linked job outcomes.
459	    ///
460	    /// Called on each cron tick. Finds routine runs that are still `running`
461	    /// with a linked `job_id`, checks the job state, and finalizes the run
462	    /// when the job reaches a completed or terminal state.
463	    ///
464	    /// Only processes runs started **before** this engine's boot time, so it
465	    /// never races with `FullJobWatcher` instances from the current process.
466	    /// This makes it safe to call on every tick as a crash-recovery mechanism.
467	    pub async fn sync_dispatched_runs(&self) {
468	        let runs = match self.store.list_dispatched_routine_runs().await {
469	            Ok(r) => r,
470	            Err(e) => {
471	                tracing::error!("Failed to list dispatched routine runs: {}", e);
472	                return;
473	            }
474	        };
475	
476	        // Only process runs from a previous process instance. Runs started
477	        // after boot_time are actively watched by a FullJobWatcher in this
478	        // process and should not be finalized here.
479	        let orphaned: Vec<_> = runs
480	            .into_iter()
481	            .filter(|r| r.started_at < self.boot_time)
482	            .collect();
483	
484	        if orphaned.is_empty() {
485	            return;
486	        }
487	
488	        tracing::info!(
489	            "Recovering {} orphaned dispatched routine runs",
490	            orphaned.len()
491	        );
492	
493	        for run in orphaned {
494	            let job_id = match run.job_id {
495	                Some(id) => id,
496	                None => continue, // Should not happen (query filters), but guard anyway
497	            };
498	
499	            // Fetch the linked job
500	            let job = match self.store.get_job(job_id).await {
501	                Ok(Some(j)) => j,
502	                Ok(None) => {
503	                    // Orphaned: job record was deleted or never persisted
504	                    tracing::warn!(
505	                        run_id = %run.id,
506	                        job_id = %job_id,
507	                        "Linked job not found, marking routine run as failed"
508	                    );
509	                    self.complete_dispatched_run(
510	                        &run,
511	                        RunStatus::Failed,
512	                        &format!("Linked job {job_id} not found (orphaned)"),
513	                    )
514	                    .await;
515	                    continue;
516	                }
517	                Err(e) => {
518	                    tracing::error!(
519	                        run_id = %run.id,
520	                        job_id = %job_id,
521	                        "Failed to fetch linked job: {}", e
522	                    );
523	                    continue;
524	                }
525	            };
526	
527	            // Map job state to final run status
528	            let final_status = match job.state {
529	                JobState::Completed | JobState::Submitted | JobState::Accepted => {
530	                    Some(RunStatus::Ok)
531	                }
532	                JobState::Failed | JobState::Cancelled => Some(RunStatus::Failed),
533	                // Pending, InProgress, Stuck — still running
534	                _ => None,
535	            };
536	
537	            let status = match final_status {
538	                Some(s) => s,
539	                None => continue, // Job still active, check again next tick
540	            };
541	
542	            // Build summary
543	            let summary = if status == RunStatus::Failed {
544	                match self.store.get_agent_job_failure_reason(job_id).await {
545	                    Ok(Some(reason)) => format!("Job {job_id} failed: {reason}"),
546	                    _ => format!("Job {job_id} {}", job.state),
547	                }
548	            } else {
549	                format!("Job {job_id} completed successfully")
550	            };
551	
552	            self.complete_dispatched_run(&run, status, &summary).await;
553	        }
554	    }
