1167	/// Execute a full-job routine by dispatching to the scheduler.
1168	///
1169	/// Fire-and-forget: creates a job via `Scheduler::dispatch_job` (which handles
1170	/// creation, metadata, persistence, and scheduling), links the routine run to
1171	/// the job, then watches it via `FullJobWatcher` until it reaches a
1172	/// non-active state (not Pending/InProgress/Stuck). Returns the final
1173	/// `RunStatus` mapped from the job outcome. This keeps the routine run
1174	/// active for the full job lifetime so concurrency guardrails apply.
1175	struct FullJobExecutionConfig<'a> {
1176	    title: &'a str,
1177	    description: &'a str,
1178	    max_iterations: u32,
1179	}
1180	
1181	async fn execute_full_job(
1182	    ctx: &EngineContext,
1183	    routine: &Routine,
1184	    run: &RoutineRun,
1185	    execution: &FullJobExecutionConfig<'_>,
1186	) -> Result<(RunStatus, Option<String>, Option<i32>), RoutineError> {
1187	    match ctx.sandbox_readiness {
1188	        SandboxReadiness::Available => {}
1189	        SandboxReadiness::DisabledByConfig => {
1190	            return Err(RoutineError::JobDispatchFailed {
1191	                reason: "Sandboxing is disabled (SANDBOX_ENABLED=false). \
1192	                         Full-job routines require sandbox."
1193	                    .to_string(),
1194	            });
1195	        }
1196	        SandboxReadiness::DockerUnavailable => {
