147	/// Compute how long to sleep until the next occurrence of `fire_at` in `tz`.
148	///
149	/// If the target time today is still in the future, sleep until then.
150	/// Otherwise sleep until the same time tomorrow.
151	fn duration_until_next_fire(fire_at: chrono::NaiveTime, tz: Tz) -> Duration {
152	    let now = chrono::Utc::now().with_timezone(&tz);
153	    let today = now.date_naive();
154	
155	    // Try to build today's target datetime in the given timezone.
156	    // `.earliest()` picks the first occurrence if DST creates ambiguity.
157	    let candidate = tz.from_local_datetime(&today.and_time(fire_at)).earliest();
158	
159	    let target = match candidate {
160	        Some(t) if t > now => t,
161	        _ => {
162	            // Already past (or ambiguous) — schedule for tomorrow
163	            let tomorrow = today + chrono::Duration::days(1);
164	            tz.from_local_datetime(&tomorrow.and_time(fire_at))
165	                .earliest()
166	                .unwrap_or_else(|| now + chrono::Duration::days(1))
167	        }
168	    };
169	
170	    let secs = (target - now).num_seconds().max(1) as u64;
171	    Duration::from_secs(secs)
172	}
