311	    /// Run a single heartbeat check.
312	    pub async fn check_heartbeat(&self) -> HeartbeatResult {
313	        // Get the heartbeat checklist
314	        let checklist = match self.workspace.heartbeat_checklist().await {
315	            Ok(Some(content)) if !is_effectively_empty(&content) => content,
316	            Ok(_) => return HeartbeatResult::Skipped,
317	            Err(e) => return HeartbeatResult::Failed(format!("Failed to read checklist: {}", e)),
318	        };
319	
320	        // Build the heartbeat prompt
321	        let prompt = format!(
322	            "Read the HEARTBEAT.md checklist below and follow it strictly. \
323	             Do not infer or repeat old tasks. Check each item and report findings.\n\
324	             \n\
325	             If nothing needs attention, reply EXACTLY with: HEARTBEAT_OK\n\
326	             \n\
327	             If something needs attention, provide a concise summary of what needs action.\n\
328	             \n\
329	             ## HEARTBEAT.md\n\
330	             \n\
331	             {}",
332	            checklist
333	        );
334	
335	        // Get the system prompt for context
336	        let system_prompt = match self.workspace.system_prompt().await {
337	            Ok(p) => p,
338	            Err(e) => {
339	                tracing::warn!("Failed to get system prompt for heartbeat: {}", e);
340	                String::new()
341	            }
342	        };
343	
344	        // Run the agent turn
345	        let messages = if system_prompt.is_empty() {
346	            vec![ChatMessage::user(&prompt)]
347	        } else {
348	            vec![
349	                ChatMessage::system(&system_prompt),
350	                ChatMessage::user(&prompt),
351	            ]
352	        };
353	
354	        // Use the model's context_length to set max_tokens. The API returns
355	        // the total context window; we cap output at half of that (the rest is
356	        // the prompt) with a floor of 4096.
357	        let max_tokens = match self.llm.model_metadata().await {
358	            Ok(meta) => {
359	                let from_api = meta.context_length.map(|ctx| ctx / 2).unwrap_or(4096);
360	                from_api.max(4096)
361	            }
362	            Err(e) => {
363	                tracing::warn!(
364	                    "Could not fetch model metadata, using default max_tokens: {}",
365	                    e
366	                );
367	                4096
368	            }
369	        };
370	
371	        let request = CompletionRequest::new(messages)
372	            .with_max_tokens(max_tokens)
373	            .with_temperature(0.3);
374	
375	        let reasoning =
376	            Reasoning::new(self.llm.clone()).with_model_name(self.llm.active_model_name());
377	        let (content, _usage) = match reasoning.complete(request).await {
378	            Ok(r) => r,
379	            Err(e) => return HeartbeatResult::Failed(format!("LLM call failed: {}", e)),
380	        };
381	
382	        let content = content.trim();
383	
384	        // Guard against empty content. Reasoning models (e.g. GLM-4.7) may
385	        // burn all output tokens on chain-of-thought and return content: null.
386	        if content.is_empty() {
387	            return HeartbeatResult::Failed("LLM returned empty content.".to_string());
388	        }
389	
390	        // Check if nothing needs attention
391	        if content == "HEARTBEAT_OK" || content.contains("HEARTBEAT_OK") {
392	            return HeartbeatResult::Ok;
393	        }
394	
395	        HeartbeatResult::NeedsAttention(content.to_string())
396	    }
